raw:
{
  "spells": [
    {
      "id": "spell_fire_01",
      "theory": "火星术把少量魔力压缩在指尖与火绒接触的平面上，使干燥纤维自身的热量在瞬间集中，越过燃点后自行维持微小火焰。火绒须实际存在并保持干燥，湿柴因水分吸热无法达到燃点，活物体表不断散失热量也不在目标之列。魔力只完成最初的点火，之后燃烧依靠火绒与空气，不再受施法者控制，因此火绒数量与摆放决定火势大小。",
      "casting": "拇指与食指捏住一撮干火绒，其余手指收拢，将魔力沿食指送到指尖，感到刺热时松开火绒并退开半步。若指尖发麻，应重新取绒再做。",
      "failure": "火绒只冒出一缕青烟便炭化，没有明火，接触过魔力的绒料会变脆，再点需要换新绒。有时火星溅到指缝，造成针尖大的灼点，虽不严重却影响后续捏取。",
      "counters": [
        "用水雾或湿布覆盖火绒，水分吸走热量使燃点无法达到。",
        "将火绒与施法指尖隔开一掌距离，魔力无法在纤维上集中。"
      ],
      "socialConsequences": "河谷乡民在集市上常请会此术的人点烟斗或引灶，报酬是几枚铜币或一顿饭。城市消防公会记录纵火案时会追查谁在禁燃区使用火星术，即便只是点烟，也可能被要求说明火绒来源。港口装卸工依赖它点燃信号灯，但货主若发现有人对着帆布练习，会立即要求赔偿并报告港务。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常点不着，火绒被烧成黑末却无明火。",
        "百次练习后能稳定点燃干燥火绒，仍需避开风口。",
        "熟练者可在三米内准确点着指定绒堆，不波及旁边。",
        "更高熟练度让火星在指尖停留更短，几乎不灼伤自己。"
      ]
    },
    {
      "id": "spell_fire_02",
      "theory": "暖掌术让魔力在手掌皮肤与浅层肌肉间循环，摩擦般产生温和热量，再通过直接接触传给受术对象。热量最高只到三十八摄氏度，与人体温相近，因此揉面时不会烫伤手或面团。掌心离开接触物后，热量不再传递，余温在三十秒内散尽。它不能作用于远物，也无法大范围加热空气，只适合揉面、暖手或给婴儿捂被。",
      "casting": "双掌合拢快速搓动三次，再将掌心贴住目标，保持接触并缓慢呼气，感到掌心均匀发热即可。若某处过热，立即移开手掌。",
      "failure": "热量分布不匀，掌心某点突然烫到四十五摄氏度以上，接触者会缩手并留下红印。有时魔力只暖了施法者自己的手，目标仍是凉的，搓手动作重复多次也无改善。",
      "counters": [
        "用湿毛巾裹住目标，水蒸发带走热量使温度无法累积。",
        "在施法者与目标之间垫一块厚布，阻断直接接触传热。"
      ],
      "socialConsequences": "西陲河谷的乡约允许在公共集会上用暖掌术为老人暖手，但若因此烫伤他人，须由见证人裁定赔偿。中陆城市的面包师愿意雇熟练者揉面，因为手温稳定能提高发面质量；同行的学徒则抱怨这会让老师傅少雇人手。琥珀海岸的船医在冷雨夜用此术为伤员保暖，港务规定若因暖掌造成伤口恶化，须追究施术者责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时掌心忽冷忽热，揉面常把面团局部烫硬。",
        "百余次练习后能维持三十八度左右，持续三十秒。",
        "熟练者能均匀暖透一块面团，不留下热点。",
        "更高熟练度让温度在接触瞬间即稳定，移开即散。"
      ]
    },
    {
      "id": "spell_fire_03",
      "theory": "烘衣术将魔力送入一件衣物的纤维之间，使水分子获得足够能量脱离纤维表面，化为水汽散入空气。热量始终低于纤维与染料的损伤阈值，因此正常施放保留颜色与织物强度。它只作用于一件衣物，帆布、仓库货物或成堆布料不在目标之内。衣物须实际存在并含有潮气，干燥衣物不会产生额外效果，排出的水汽会略微提高周围湿度。",
      "casting": "双手提起衣物两肩，从领口向下缓慢抚过三次，每次抚过时送入一缕魔力，感到布料由凉转温即可停止。若布料发烫，应立即松手。",
      "failure": "水汽排出不均，衣物部分干硬、部分仍湿，折叠处可能因局部过热而褪色。有时魔力只烘干了外层，内衬依旧潮湿，穿着后反而更冷，需要重新晾晒。",
      "counters": [
        "将衣物浸入冷水，水分不断补充使干燥无法完成。",
        "用油布完全包裹衣物，水汽无法散出，烘衣过程自行停止。"
      ],
      "socialConsequences": "河谷的洗衣妇在雨季用烘衣术帮乡邻烘干唯一的外出服，收费低廉，但若褪色会被要求赔偿。中陆城市的旅店老板欢迎此术，因为客人不必穿湿衣上路；染坊主则担心有人用烘衣术处理染坏布料后冒充新货，要求行会登记施术者。琥珀海岸的码头工人用它烘干工装，港务规定若因烘衣引发货舱潮湿，须追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时衣物外层干、内衬仍湿，需反复施术。",
        "百余次练习后能均匀排湿，保留染料与纤维。",
        "熟练者可在三十秒内烘干一件厚外套而不损伤。",
        "更高熟练度让水汽散得更快，周围湿度几乎不升。"
      ]
    }
  ]
}
